'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'../..');
const src=fs.readFileSync(path.join(root,'docs/scifi-ui/scripts/formatx-core-real3d-v20.js'),'utf8');
const css=fs.readFileSync(path.join(root,'docs/scifi-ui/styles/formatx-core-real3d-v20.css'),'utf8');

assert.match(src,/const VERSION = 'v21'/,'v21 engine revision missing');
assert.match(src,/fxCoreReal3dRevision = 'ready-v21'/,'v21 runtime revision marker missing');
assert.match(src,/fxCoreRendererRevision = 'single-webgl2-indexed-3d-v21'/,'v21 renderer revision marker missing');
assert.match(src,/fxCoreReal3d = 'ready-v20'/,'v20 compatibility marker must remain');
assert.match(src,/fxCoreRenderer = 'single-webgl2-indexed-3d-v20'/,'v20 renderer compatibility marker must remain');
assert.match(src,/canvas\.getContext\('webgl2'/,'single WebGL2 context missing');
assert.equal((src.match(/getContext\('webgl2'/g)||[]).length,1,'v21 must create exactly one WebGL2 context');
assert.match(src,/gl\.enable\(gl\.DEPTH_TEST\)/,'depth testing missing');
assert.match(src,/gl\.drawElements\(gl\.TRIANGLES/,'indexed triangles missing');
assert.match(src,/gl\.drawElements\(gl\.LINES/,'indexed integrated lines missing');
assert.match(src,/function referenceRadius\(angle\)/,'reference p-norm radius function missing');
assert.match(src,/const p = \.94/,'p-norm exponent missing');
assert.match(src,/return \.075 \+ \.925 \* lp/,'reference four-tip radius calibration missing');
assert.match(src,/radius \* t \* 1\.22/,'reference vertical geometry calibration missing');
assert.match(src,/for \(const ring of \[4, 8, radialSegments\]\)/,'reduced membrane ring layout missing');
assert.match(src,/angularSegments \/ 8/,'reduced spoke density missing');
assert.match(src,/float membrane=band\(diamond,\.34,\.026\)/,'structured diamond membranes missing');
assert.match(src,/float reactorRings=band\(radial,\.20,\.018\)/,'structured reactor rings missing');
assert.match(src,/float axisX=exp\(-abs\(p\.x\)\*18\.0\)/,'vertical energy axis missing');
assert.match(src,/float axisY=exp\(-abs\(p\.y\)\*15\.0\)/,'horizontal energy axis missing');
assert.match(src,/float violetArc=/,'controlled violet arc missing');
assert.match(src,/vec3 cyan=vec3\(\.010,\.76,1\.55\)/,'reference cyan chroma missing');
assert.match(src,/vec3 violet=vec3\(\.88,\.055,1\.48\)/,'reference violet chroma missing');
assert.match(src,/const y=mobile\?\.50:\.03/,'mobile reference upshift missing');
assert.match(src,/const scale=\(mobile\?1\.00:\.98\)\*pulse/,'mobile reference scale missing');
assert.match(src,/scaling\(\.68\*ringPulse/,'smaller outer reactor torus missing');
assert.match(src,/scaling\(\.50,\.50,\.50\)/,'smaller middle reactor torus missing');
assert.match(src,/scaling\(\.34,\.34,\.34\)/,'smaller inner reactor torus missing');
assert.match(src,/scaling\(\.175,\.175,\.175\)/,'smaller reactor halo missing');
assert.match(src,/reactorScale=\.078/,'smaller reactor sphere missing');
assert.match(src,/\.18\+cinematic\.energy\*\.10/,'reduced cyan spoke overlay missing');
assert.match(src,/\.09\+cinematic\.energy\*\.05/,'reduced violet spoke overlay missing');
assert.match(src,/reference-pnorm-four-tip-shell-v21/,'shape marker missing');
assert.match(src,/axis-membrane-rings-v21/,'structured highlight marker missing');
assert.match(src,/reference-upshift-wide-real3d-v21/,'mobile composition marker missing');
assert.match(src,/film-reactive-v1/,'cinematic state machine missing');
assert.match(src,/adaptive-60-plus-fps/,'adaptive performance target missing');
assert.doesNotMatch(src,/drawImage\s*\(|new Image\s*\(|background-image/i,'real3D MAG must not be image-backed');
assert.doesNotMatch(src,/THREE\b|three\.js|babylon|gsap/i,'third-party scene engine forbidden');
assert.doesNotMatch(src,/preventDefault\s*\(\)/,'MAG runtime must not capture page scrolling except WebGL context loss');
assert.match(css,/pointer-events:\s*none/,'real3D canvas must not capture input');
assert.match(css,/100dvh/,'dynamic viewport sizing missing');
console.log('PASS: single-context real3D v21 uses reference p-norm geometry, structured crystal lighting, smaller reactor hardware, compatibility markers, and adaptive native WebGL2 rendering.');
